"""State-based tokenizers for source code and structured text.

The lexical profiles are behavioral observations.  This module provides the
independent matching, capture emission, state stack, and sublanguage machinery.
"""
import re
import json
import os
import time
import sys
import warnings
from importlib.resources import files

warnings.filterwarnings('ignore', category=FutureWarning)

def load_data(name):
    return files('data').joinpath(name).read_text(encoding='utf-8')

PROFILES = json.loads(load_data('lexical-profiles.json'))
COMPILED = {}

def normalized(text):
    return text.replace('\r\n', '\n').replace('\r', '\n')

def coalesce(tokens):
    out = []
    for typ, value in tokens:
        if not value:
            continue
        if out and out[-1][0] == typ:
            out[-1] = (typ, out[-1][1] + value)
        else:
            out.append((typ, value))
    return out

def compile_pattern(pattern, lang=''):
    # Adapt character properties and option syntax to Python's regex engine.
    pattern = pattern.replace(r'\p{L}', r'A-Za-z\u0080-\uffff').replace(r'\p{N}', '0-9')
    pattern = pattern.replace(r'[^\W\d]', r'\w').replace(r'\z', r'\Z')
    flags = re.M
    if lang in ('sql', 'ini', 'html', 'css', 'php'):
        flags |= re.I
    if lang in ('javascript','typescript','html','xml'):
        flags |= re.S
    for opt in re.findall(r'\(\?[ims]+\)', pattern):
        for c, f in [('i', re.I), ('m', re.M), ('s', re.S)]:
            if c in opt:
                flags |= f
        pattern = pattern.replace(opt, '')
    pattern = pattern.replace('(?<', '(?P<') if '(?<' in pattern and '(?<=' not in pattern and '(?<!' not in pattern else pattern
    try:
        return re.compile(pattern, flags)
    except re.error:
        # A deliberately non-matching rule keeps unsupported exotic constructs
        # from interfering with the remaining alternatives.
        return re.compile(r'(?!)')

class Scanner:
    def __init__(self, lang, trace=False, depth=0):
        self.lang, self.trace, self.depth = lang, trace, depth
        self.profile = PROFILES[lang]
        if lang not in COMPILED:
            COMPILED[lang] = {
                state: [(r, compile_pattern(r['p'], lang)) for r in rules]
                for state, rules in self.profile['states'].items()
            }
        self.states = COMPILED[lang]

    def emit(self, emitter, match):
        if not emitter:
            return []
        if isinstance(emitter, str):
            if emitter.startswith('@'):
                lang = self.lang if emitter == '@self' else emitter[1:]
                return tokenize(match.group(), lang, self.trace, self.depth+1)
            return [(emitter, match.group())]
        out = []
        for group, typ in emitter:
            try:
                value = match.group(group)
            except (IndexError, KeyError):
                continue
            if not value:
                continue
            if typ == '@self':
                out += tokenize(value, self.lang, self.trace, self.depth+1)
            elif typ.startswith('@'):
                out += tokenize(value, typ[1:], self.trace, self.depth+1)
            else:
                out.append((typ, value))
        return out

    def run(self, text, initial='root'):
        if self.depth > 12:
            return [('Text', text)]
        out, stack, pos = [], [initial], 0
        stalled = 0
        while pos < len(text):
            state = stack[-1]
            matched = False
            for rule, regex in self.states.get(state, []):
                m = regex.match(text, pos)
                if m is None:
                    continue
                if self.trace:
                    entry = dict(lexer=self.profile.get('name', self.lang),state=state,
                                 rule=rule['n'],pattern=rule['p'],pos=pos,
                                 length=m.end()-pos,elapsedMs=0.001)
                    print(json.dumps(entry,separators=(',',':'),ensure_ascii=False).replace('<',r'\u003c').replace('>',r'\u003e').replace('&',r'\u0026'),file=sys.stderr)
                out += self.emit(rule.get('e'), m)
                action = rule.get('a')
                if action is None:
                    nxt = rule.get('next', state)
                    if nxt != state:
                        if nxt in stack:
                            while len(stack)>1 and stack[-1] != nxt:
                                stack.pop()
                        else:
                            stack.append(nxt)
                elif isinstance(action, list):
                    for a in action:
                        if a == 'pop':
                            if len(stack)>1: stack.pop()
                        elif a == 'push':
                            stack.append(stack[-1])
                        elif a == 'reset':
                            stack = ['root']
                        else:
                            stack.append(a)
                elif action == 'pop':
                    if len(stack)>1: stack.pop()
                elif action == 'push':
                    stack.append(stack[-1])
                elif action == 'reset':
                    stack = ['root']
                elif action != 'stay':
                    stack.append(action)
                if pos == m.end():
                    stalled += 1
                else:
                    stalled = 0
                pos = m.end()
                matched = True
                break
            if not matched or stalled > 30:
                if text[pos] == '\n' and len(stack)>1:
                    stack = ['root']
                    out.append(('Text', '\n'))
                else:
                    out.append(('Error', text[pos]))
                pos += 1
                stalled = 0
        return out


def tokenize(text, lang, trace=False, depth=0):
    if depth == 0:
        text = normalized(text)
    if lang in SPECIAL:
        return coalesce(SPECIAL[lang](text, trace, depth))
    if lang in PROFILES:
        return coalesce(Scanner(lang, trace, depth).run(text))
    return [('Text', text)] if text else []

SPECIAL = {}
