from formatters import Style, json_output, tokens_output, html_output, svg_output, ansi_output, parse_ranges, quote_go

FORMATS=['html','json','noop','svg','terminal','terminal16','terminal16m','terminal256','terminal8','tokens']
DEFAULTS={'lexer':'autodetect','style':'swapoff','formatter':'terminal','html-tab-width':8,'html-base-line':1}
BOOLS=set('help version list unbuffered trace check fail json html svg html-styles html-all-styles html-only html-inline-styles html-lines html-lines-table html-prevent-surrounding-pre html-linkable-lines'.split())
STRINGS=set('filename lexer style formatter html-prefix html-lines-style html-highlight html-highlight-style'.split())
INTS={'html-tab-width','html-base-line'}
SHORTS={'h':'help','l':'lexer','s':'style','f':'formatter'}

class Failure(Exception):
    def __init__(self,message,code=1):
        self.message,self.code=message,code


def parse_cli(args):
    opt=DEFAULTS.copy(); paths=[];literal=False;i=0
    while i<len(args):
        arg=args[i];i+=1
        if not literal and arg=='--':literal=True;continue
        if not literal and arg.startswith('--') and len(arg)>2:
            parts=arg[2:].split('=',1);name=parts[0]
            value=parts[1] if len(parts)>1 else None
            if name not in BOOLS|STRINGS|INTS:raise Failure('unknown flag --'+name,80)
            shown='--'+name
        elif not literal and arg.startswith('-') and arg!='-':
            c=arg[1]
            if c not in SHORTS:
                raise Failure('unknown flag -'+c+', did you mean one of "-h", "-l", "-s", "-f"?',80)
            name=SHORTS[c];shown='--'+name
            if name in BOOLS:
                value=None
                if len(arg)>2:args.insert(i,'-'+arg[2:])
            else:value=arg[2:] if len(arg)>2 else None
        else:
            paths.append(arg)
            continue
        if name in BOOLS:
            if value is None:v=True
            elif value.lower() in ('true','1','yes'):v=True
            elif value.lower() in ('false','0','no'):v=False
            else:raise Failure(shown+': bool value must be true, 1, yes, false, 0 or no but got '+quote_go(value),80)
            opt[name]=v
        else:
            if value is None:
                if i>=len(args):
                    kind='int' if name in INTS else 'string'
                    raise Failure(shown+': expected '+kind+' value but got "EOL" (<EOL>)',80)
                value=args[i];i+=1
                if value.startswith('--') or value.startswith('-') and len(value)==2 and name not in INTS:
                    raise Failure(shown+': expected string value but got '+quote_go(value)+' (long flag)',80)
            if name in INTS:
                if not re.fullmatch('[+-]?\d+',value) or not -(1<<63)<=int(value)<1<<63:
                    raise Failure(shown+': expected a valid 64 bit int but got '+quote_go(value),80)
                value=int(value)
