def http_tokens(text,trace=False,depth=0):
    out=[]
    first,sep,rest=text.partition('\n')
    req=re.fullmatch(r'(\w+)(\s+)(\S+)(\s+)(HTTP)(/)([0-9.]+)(\r?)',first)
    resp=re.fullmatch(r'(HTTP)(/)([0-9.]+)(\s+)([0-9]+)(\s*)(.*?)(\r?)',first)
    if req:
        out.extend(zip(['NameFunction','Text','NameNamespace','Text','KeywordReserved','Operator','LiteralNumber','Text'],req.groups()))
    elif resp:
        out.extend(zip(['KeywordReserved','Operator','LiteralNumber','Text','LiteralNumber','Text','NameException','Text'],resp.groups()))
    else:return [('Error',text)] if text else []
    if sep:out.append(('Text','\n'))
    content_type=''
    while rest:
        line,sep,remaining=rest.partition('\n')
        if not line.strip():
            out.append(('Text',line+sep));rest=remaining;break
        header=re.fullmatch(r'([^:\s]+)(:)([ \t]*)(.*)',line)
        if not header:
            out.append(('Error',rest));return out
        out.extend(zip(['Name','Operator','Text','Literal'],header.groups()))
        if sep:out.append(('Text','\n'))
        if header[1].lower()=='content-type':content_type=header[4].split(';')[0].strip()
        rest=remaining
    langs={'application/json':'json','text/html':'html','application/xml':'xml','text/xml':'xml','text/css':'css','application/javascript':'javascript','text/javascript':'javascript','text/plain':'plaintext'}
    if content_type in langs:out.extend(tokenize(rest,langs[content_type],trace,depth+1))
    elif rest:out.append(('Generic',rest))
    return out

